package com.bank.risk.service;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.PriorityQueue;
import java.util.logging.Logger;

// Computes the median of every size-K window using two heaps + lazy deletion.
public class WindowMedian {
    private static final Logger log = Logger.getLogger(WindowMedian.class.getName());

    private final PriorityQueue<BigDecimal> maxHeap =
            new PriorityQueue<>(Comparator.reverseOrder());
    private final PriorityQueue<BigDecimal> minHeap = new PriorityQueue<>();
    private final Map<BigDecimal, Integer> toRemove = new HashMap<>();
    private int balance; // logical size(maxHeap) - size(minHeap)

    public List<BigDecimal> medians(List<BigDecimal> amounts, int k) {
        List<BigDecimal> result = new ArrayList<>();
        for (int i = 0; i < amounts.size(); i++) {
            add(amounts.get(i));
            if (i >= k) {
                remove(amounts.get(i - k)); // element leaving the window
            }
            if (i >= k - 1) {
                BigDecimal med = currentMedian(k);
                result.add(med);
                log.info(() -> "Window median = " + med);
            }
        }
        return result;
    }

    private void add(BigDecimal num) {
        if (maxHeap.isEmpty() || num.compareTo(maxHeap.peek()) <= 0) {
            maxHeap.offer(num); balance++;
        } else {
            minHeap.offer(num); balance--;
        }
        rebalance();
    }

    private void remove(BigDecimal num) {
        toRemove.merge(num, 1, Integer::sum); // schedule lazy deletion
        if (!maxHeap.isEmpty() && num.compareTo(maxHeap.peek()) <= 0) {
            balance--;
            if (num.compareTo(maxHeap.peek()) == 0) prune(maxHeap);
        } else {
            balance++;
            if (!minHeap.isEmpty() && num.compareTo(minHeap.peek()) == 0) prune(minHeap);
        }
        rebalance();
    }

    private void rebalance() {
        if (balance > 1) { minHeap.offer(maxHeap.poll()); balance -= 2; prune(maxHeap); }
        else if (balance < 0) { maxHeap.offer(minHeap.poll()); balance += 2; prune(minHeap); }
    }

    private void prune(PriorityQueue<BigDecimal> heap) {
        while (!heap.isEmpty() && toRemove.getOrDefault(heap.peek(), 0) > 0) {
            toRemove.merge(heap.peek(), -1, Integer::sum);
            heap.poll();
        }
    }

    private BigDecimal currentMedian(int k) {
        prune(maxHeap); prune(minHeap);
        if (k % 2 == 1) {
            return maxHeap.peek();
        }
        return maxHeap.peek().add(minHeap.peek())
                .divide(new BigDecimal("2"), 2, RoundingMode.HALF_UP);
    }
}
