package com.bank.risk;

import com.bank.risk.service.WindowMedian;
import java.math.BigDecimal;
import java.util.List;
import java.util.logging.Logger;

public class WindowMedianApplication {
    private static final Logger log = Logger.getLogger(WindowMedianApplication.class.getName());

    public static void main(String[] args) {
        List<BigDecimal> amounts = List.of(
                new BigDecimal("1000"), new BigDecimal("2000"), new BigDecimal("500"),
                new BigDecimal("3000"), new BigDecimal("1500"));
        WindowMedian wm = new WindowMedian();
        log.info("NBI rolling medians (k=3): " + wm.medians(amounts, 3));
    }
}
